1	// Package credit 实现本地课程学分与免修的登记、持久化与核对。
2	//
3	// 基本对象：
4	//   - 学生（Student）：以唯一编号登记；
5	//   - 课程（Course）：唯一编号、名称、正整数学分，初始开放，可停开/恢复；
6	//   - 课程要求（Requirement）：属于某名学生，编号在该学生名下唯一，指向一门课程；
7	//   - 修读（Enrollment）：属于某名学生的一项要求，记录学期与编号，结果为
8	//     选课/通过/未通过；
9	//   - 免修（Waiver）：明确指向该学生的一项要求，带编号与非空依据，状态为
10	//     有效/已拒绝/已撤销。
11	//
12	// 所有“重复登记相同内容”的操作都幂等：返回原记录、不新增数据；内容冲突的
13	// 重复请求一律拒绝并保留原记录。
14	package credit
15	
16	import (
17		"errors"
18		"fmt"
19		"strings"
20	)
21	
22	// Result 是修读结果。
23	type Result string
24	
25	const (
26		// Enrolled 已选课、尚未有结果，不计学分。
27		Enrolled Result = "enrolled"
28		// Passed 通过。
29		Passed Result = "passed"
30		// Failed 未通过，不计学分。
31		Failed Result = "failed"
32	)
33	
34	// WaiverStatus 是免修申请的状态。
35	type WaiverStatus string
36	
37	const (
38		// WaiverApproved 有效免修：满足对应要求并获得课程学分。
39		WaiverApproved WaiverStatus = "approved"
40		// WaiverRejected 已拒绝：申请内容与拒绝原因保留在免修历史中。
41		WaiverRejected WaiverStatus = "rejected"
42		// WaiverRevoked 已撤销：原依据保留，要求按修读情况重新判定。
43		WaiverRevoked WaiverStatus = "revoked"
44	)
45	
46	// Course 课程：编号唯一，学分为正整数。
47	type Course struct {
48		ID     string `json:"id"`
49		Name   string `json:"name"`
50		Credit int    `json:"credit"`
51		Open   bool   `json:"open"`
52	}
53	
54	// Student 学生：只有唯一编号。
55	type Student struct {
56		ID string `json:"id"`
57	}
58	
59	// Requirement 课程要求：在所属学生名下编号唯一，指向一门已登记课程。
60	type Requirement struct {
61		ID        string `json:"id"`
62		StudentID string `json:"student"`
63		CourseID  string `json:"course"`
64	}
65	
66	// Enrollment 修读：属于某名学生的一项要求，编号在该学生名下唯一。
67	type Enrollment struct {
68		ID        string `json:"id"`
69		StudentID string `json:"student"`
70		ReqID     string `json:"req"`
71		Term      string `json:"term"`
72		Result    Result `json:"result"`
73		// ResultSeq 是首次提交结果的先后序号，用于确定“最先提交的通过记录”。
74		ResultSeq int `json:"resultSeq,omitempty"`
75	}
76	
77	// Waiver 免修申请。被拒绝或撤销后记录仍保留在免修历史中。
78	type Waiver struct {
79		ID        string       `json:"id"`
80		StudentID string       `json:"student"`
81		ReqID     string       `json:"req"`
82		Basis     string       `json:"basis"`
83		Status    WaiverStatus `json:"status"`
84		// Reason 记录拒绝原因或撤销原因。
85		Reason string `json:"reason,omitempty"`
86	}
87	
88	// Store 是全部记录的内存集合，零值即可用。
89	type Store struct {
90		courses      []*Course
91		students     []*Student
92		requirements []*Requirement
93		enrollments  []*Enrollment
94		waivers      []*Waiver
95	
96		courseByID    map[string]*Course
97		studentByID   map[string]*Student
98		reqByKey      map[ownerKey]*Requirement // (student, reqID)
99		reqByDup      map[ownerKey]string       // (student, course) -> reqID
100		enrByKey      map[ownerKey]*Enrollment  // (student, enrID)
101		waiverByKey   map[ownerKey]*Waiver      // (student, waiverID)
102		nextResultSeq int
103		// dirty 记录自加载以来是否发生过需要落盘的变更（新建被拒绝的免修也算）。
104		dirty bool
105	}
106	
107	// ownerKey 是“所属学生编号 + 该学生名下编号”的复合键。两部分各自按完整
108	// 文字参与比较，因此要求是否存在必须以所属学生和编号都完全一致为准。
109	// 不能用 student + "\x00" + id 之类的字符串拼接：JSON 解码后的编号本身
110	// 允许包含 U+0000 等任意字符，拼接键会把 ("s","x\x00r") 与 ("s\x00x","r")
111	// 两项不同学生的记录混成同一键，导致合法文件被判重复或免修借用他人要求。
112	type ownerKey struct {
113		student string
114		id      string
115	}
116	
117	func reqKey(student, id string) ownerKey { return ownerKey{student, id} }
118	func dupKey(student, course string) ownerKey {
119		return ownerKey{student, course}
120	}
121	
122	// blankBasis 报告一份免修依据是否不含任何实际文字：空字符串，或全部由空白
123	// 字符组成。空白按 Unicode 判定，除空格、制表符、换行、回车外还包括全角
124	// 空格（U+3000）、不换行空格（U+00A0）等，混合使用这些字符仍算没有依据。
125	//
126	// 该判定只用于读取校验，绝不修剪或改写已保存的依据原文——依据中含有实际
127	// 文字时，其前后与中间原有的空白必须原样保留在免修历史中。
128	func blankBasis(basis string) bool {
129		return strings.TrimSpace(basis) == ""
130	}
131	
132	func newStore() *Store {
133		s := &Store{}
134		s.resetIndexes()
135		return s
136	}
137	
138	func (s *Store) resetIndexes() {
139		s.courseByID = map[string]*Course{}
140		s.studentByID = map[string]*Student{}
141		s.reqByKey = map[ownerKey]*Requirement{}
142		s.reqByDup = map[ownerKey]string{}
143		s.enrByKey = map[ownerKey]*Enrollment{}
144		s.waiverByKey = map[ownerKey]*Waiver{}
145	}
146	
147	// NewStore 返回空记录集。
148	func NewStore() *Store { return newStore() }
149	
150	// Dirty 报告自加载以来是否发生过需要落盘的变更。
151	// 被拒绝但要保留在免修历史中的申请也计为变更；纯幂等返回与只读核对不计。
152	func (s *Store) Dirty() bool { return s.dirty }
153	
154	// ---------- 查询 ----------
155	
156	// Course 按编号返回课程；不存在返回 nil。
157	func (s *Store) Course(id string) *Course { return s.courseByID[id] }
158	
159	// Courses 按登记顺序返回全部课程。
160	func (s *Store) Courses() []*Course { return append([]*Course(nil), s.courses...) }
161	
162	// Student 按编号返回学生；不存在返回 nil。
163	func (s *Store) Student(id string) *Student { return s.studentByID[id] }
164	
165	// Students 按登记顺序返回全部学生。
166	func (s *Store) Students() []*Student { return append([]*Student(nil), s.students...) }
167	
168	// Requirement 返回某学生名下的要求；不存在（包括要求属于其他学生）返回 nil。
169	func (s *Store) Requirement(student, reqID string) *Requirement {
170		return s.reqByKey[reqKey(student, reqID)]
171	}
172	
173	// Requirements 返回某学生的全部要求（按登记顺序）；学生不存在返回 nil。
174	func (s *Store) Requirements(student string) []*Requirement {
175		if _, ok := s.studentByID[student]; !ok {
176			return nil
177		}
178		var out []*Requirement
179		for _, r := range s.requirements {
180			if r.StudentID == student {
181				out = append(out, r)
182			}
183		}
184		return out
185	}
186	
187	// AllRequirements 按登记顺序返回全部要求。
188	func (s *Store) AllRequirements() []*Requirement {
189		return append([]*Requirement(nil), s.requirements...)
190	}
191	
192	// Enrollment 返回某学生名下的修读；不存在返回 nil。
193	func (s *Store) Enrollment(student, id string) *Enrollment {
194		return s.enrByKey[reqKey(student, id)]
195	}
196	
197	// Enrollments 返回某学生的全部修读（按登记顺序）；学生不存在返回 nil。
198	func (s *Store) Enrollments(student string) []*Enrollment {
199		if _, ok := s.studentByID[student]; !ok {
200			return nil
201		}
202		var out []*Enrollment
203		for _, e := range s.enrollments {
204			if e.StudentID == student {
205				out = append(out, e)
206			}
207		}
208		return out
209	}
210	
211	// Waiver 返回某学生名下的免修申请；不存在返回 nil。
212	func (s *Store) Waiver(student, id string) *Waiver {
213		return s.waiverByKey[reqKey(student, id)]
214	}
215	
216	// Waivers 返回某学生的全部免修历史（按申请顺序）；学生不存在返回 nil。
217	func (s *Store) Waivers(student string) []*Waiver {
218		if _, ok := s.studentByID[student]; !ok {
219			return nil
220		}
221		var out []*Waiver
222		for _, w := range s.waivers {
223			if w.StudentID == student {
224				out = append(out, w)
225			}
226		}
227		return out
228	}
229	
230	// ---------- 学生 ----------
231	
232	// AddStudent 登记学生。编号已存在时原样返回已有学生且 action=existed（幂等）。
233	func (s *Store) AddStudent(id string) (st *Student, action Action, err error) {
234		id = strings.TrimSpace(id)
235		if id == "" {
236			return nil, "", errors.New("学生编号不能为空")
237		}
238		if existing := s.studentByID[id]; existing != nil {
239			return existing, ActionExisted, nil
240		}
241		st = &Student{ID: id}
242		s.students = append(s.students, st)
243		s.studentByID[id] = st
244		s.dirty = true
245		return st, ActionCreated, nil
246	}
247	
248	// ---------- 课程 ----------
249	
250	// Action 描述登记类操作相对已有记录做了什么。
251	type Action string
252	
253	const (
254		// ActionCreated 新建了记录。
255		ActionCreated Action = "created"
256		// ActionExisted 记录已存在且内容一致，原样返回（幂等）。
257		ActionExisted Action = "existed"
258		// ActionUpdated 记录已存在，本次在允许范围内更新了内容。
259		ActionUpdated Action = "updated"
260	)
261	
262	// AddCourse 登记课程，学分为正整数，新课程初始开放。
263	// 编号已存在且名称、学分完全相同时原样返回（幂等），停开/开放状态不变。
264	// 编号相同但学分不同：该课程尚未被任何课程要求引用时允许修改并保持开放
265	// 状态；已经被要求引用的课程不能修改学分，请求被拒绝且课程保持不变。
266	func (s *Store) AddCourse(id, name string, credit int) (c *Course, action Action, err error) {
267		id = strings.TrimSpace(id)
268		name = strings.TrimSpace(name)
269		if id == "" {
270			return nil, "", errors.New("课程编号不能为空")
271		}
272		if name == "" {
273			return nil, "", errors.New("课程名称不能为空")
274		}
275		if credit <= 0 {
276			return nil, "", fmt.Errorf("课程学分必须是正整数，得到 %d", credit)
277		}
278		if existing := s.courseByID[id]; existing != nil {
279			if existing.Name == name && existing.Credit == credit {
280				return existing, ActionExisted, nil
281			}
282			if existing.Credit != credit && s.courseReferenced(id) {
283				return nil, "", fmt.Errorf(
284					"课程 %s 已被课程要求引用，不能修改学分（原学分 %d），原记录保留",
285					id, existing.Credit)
286			}
287			existing.Name = name
288			existing.Credit = credit
289			s.dirty = true
290			return existing, ActionUpdated, nil
291		}
292		c = &Course{ID: id, Name: name, Credit: credit, Open: true}
293		s.courses = append(s.courses, c)
294		s.courseByID[id] = c
295		s.dirty = true
296		return c, ActionCreated, nil
297	}
298	
299	// courseReferenced 报告课程是否被任何学生的课程要求引用。
300	func (s *Store) courseReferenced(id string) bool {
301		for _, r := range s.requirements {
302			if r.CourseID == id {
303				return true
304			}
305		}
306		return false
307	}
308	
309	// SetCourseOpen 设置课程开放状态。课程不存在时报错；状态相同则原样返回。
310	func (s *Store) SetCourseOpen(id string, open bool) (*Course, error) {
311		c := s.courseByID[id]
312		if c == nil {
313			return nil, fmt.Errorf("课程 %s 不存在", id)
314		}
315		if c.Open != open {
316			c.Open = open
317			s.dirty = true
318		}
319		return c, nil
320	}
321	
322	// ---------- 课程要求 ----------
323	
324	// AddRequirement 为学生登记一项指向课程的要求。
325	// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
326	// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
327	func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
328		studentID = strings.TrimSpace(studentID)
329		reqID = strings.TrimSpace(reqID)
330		courseID = strings.TrimSpace(courseID)
331		if studentID == "" || reqID == "" {
332			return nil, "", errors.New("学生编号和要求编号不能为空")
333		}
334		if _, ok := s.studentByID[studentID]; !ok {
335			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
336		}
337		c := s.courseByID[courseID]
338		if c == nil {
339			return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
340		}
341		if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
342			if existing.CourseID != courseID {
343				return nil, "", fmt.Errorf(
344					"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
345					studentID, reqID, existing.CourseID, courseID)
346			}
347			return existing, ActionExisted, nil
348		}
349		if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
350			return nil, "", fmt.Errorf(
351				"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
352		}
353		r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
354		s.requirements = append(s.requirements, r)
355		s.reqByKey[reqKey(studentID, reqID)] = r
356		s.reqByDup[dupKey(studentID, courseID)] = reqID
357		s.dirty = true
358		return r, ActionCreated, nil
359	}
360	
361	// ---------- 修读 ----------
362	
363	// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
364	// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
365	// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
366	// （已登记记录的重复提交仍按幂等返回原记录）。
367	//
368	// 学生编号、要求编号与修读编号按用户给出的完整文字参与匹配，前后空白
369	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
370	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
371	// 要求、“e1” 与 “ e1 ” 两份修读，登记必须命中编号完全一致的对象，新
372	// 修读也必须登记在完整编号的学生与要求名下并保留完整编号。完整编号找
373	// 不到学生时报告学生不存在；学生存在但名下没有该完整要求编号时报告本人
374	// 名下没有该要求——即使去掉空白能碰上另一名学生或另一项要求，也绝不
375	// 借用那份记录，更不能把修读登记到别人名下。编号为空字符串时直接拒绝；
376	// 只由空白字符组成的修读编号不得建立。学期沿用现有输入规则：前后空白
377	// 不计入学期内容，修剪后为空则拒绝。
378	func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
379		term = strings.TrimSpace(term)
380		if studentID == "" || reqID == "" || enrID == "" {
381			return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
382		}
383		if strings.TrimSpace(enrID) == "" {
384			return nil, "", errors.New("修读编号不能只由空白字符组成")
385		}
386		if term == "" {
387			return nil, "", errors.New("学期不能为空")
388		}
389		if _, ok := s.studentByID[studentID]; !ok {
390			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
391		}
392		r := s.reqByKey[reqKey(studentID, reqID)]
393		if r == nil {
394			return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
395		}
396		if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
397			if existing.ReqID != reqID || existing.Term != term {
398				return nil, "", fmt.Errorf(
399					"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
400					studentID, enrID, existing.ReqID, existing.Term, reqID, term)
401			}
402			return existing, ActionExisted, nil
403		}
404		c := s.courseByID[r.CourseID]
405		if c == nil || !c.Open {
406			return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
407		}
408		e = &Enrollment{
409			ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
410		}
411		s.enrollments = append(s.enrollments, e)
412		s.enrByKey[reqKey(studentID, enrID)] = e
413		s.dirty = true
414		return e, ActionCreated, nil
415	}
416	
417	// SubmitResult 为修读提交通过/未通过结果。
418	// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
419	// 一律拒绝并保留原记录。
420	//
421	// 学生编号与修读编号按用户给出的完整文字参与匹配，前后空白（普通空格、
422	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
423	// “s1”与“ s1 ”两名学生、同一学生名下“e1”与“ e1 ”两份修读，提交
424	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
425	// 学生存在但名下没有该完整修读编号时报告该修读不存在——即使去掉空白后
426	// 能碰上另一名学生或另一份修读，也绝不借用那份记录，更不能据此补建修读。
427	func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
428		if result != Passed && result != Failed {
429			return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
430		}
431		if _, ok := s.studentByID[studentID]; !ok {
432			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
433		}
434		e = s.enrByKey[reqKey(studentID, enrID)]
435		if e == nil {
436			return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
437		}
438		if e.Result == result {
439			return e, false, nil
440		}
441		if e.Result != Enrolled {
442			return nil, false, fmt.Errorf(
443				"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
444		}
445		s.nextResultSeq++
446		e.Result = result
447		e.ResultSeq = s.nextResultSeq
448		s.dirty = true
449		return e, true, nil
450	}
451	
452	// ---------- 免修 ----------
453	
454	// ApplyWaiver 提交免修申请，依据必须含实际文字。
455	//
456	// 首次提交且内容合法：状态为有效（approved），action=created。
457	// 目标要求不存在（含要求属于其他学生）、依据不含实际文字、或该要求已有
458	// 有效免修：申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
459	// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
460	// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
461	// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
462	//
463	// 学生编号、要求编号与免修编号按用户给出的完整文字参与匹配，前后空白
464	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
465	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
466	// 要求、“w1” 与 “ w1 ” 两份申请，提交必须命中编号完全一致的那一项，
467	// 申请也必须登记在完整编号的申请人名下。完整编号找不到学生时直接按业务
468	// 规则报错，不在任何学生名下新增历史；学生存在但名下没有该完整要求编号
469	// 时，即使去掉空白能碰上另一项要求，也绝不借用那份记录，而是按原规则在
470	// 申请人名下保存原要求编号、免修编号、依据原文与拒绝原因。编号为空字符串
471	// 时直接拒绝，不创建申请。依据含实际文字时其中的空白（包括前后空白）
472	// 原样保留；是否“没有依据”只按空白内容判定（见 blankBasis），绝不修剪
473	// 或改写依据原文。
474	func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
475		if studentID == "" || reqID == "" || waiverID == "" {
476			return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
477		}
478		if _, ok := s.studentByID[studentID]; !ok {
479			return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
480		}
481		if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
482			if existing.ReqID != reqID || existing.Basis != basis {
483				return nil, "", fmt.Errorf(
484					"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
485					studentID, waiverID, existing.ReqID, existing.Basis)
486			}
487			return existing, ActionExisted, nil
488		}
489	
490		w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
491		switch {
492		case s.reqByKey[reqKey(studentID, reqID)] == nil:
493			w.Status = WaiverRejected
494			w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
495		case blankBasis(basis):
496			w.Status = WaiverRejected
497			w.Reason = "免修依据为空"
498		default:
499			if other := s.validWaiver(studentID, reqID); other != nil {
500				w.Status = WaiverRejected
501				w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
502				break
503			}
504			w.Status = WaiverApproved
505		}
506		s.waivers = append(s.waivers, w)
507		s.waiverByKey[reqKey(studentID, waiverID)] = w
508		s.dirty = true
509		return w, ActionCreated, nil
510	}
511	
512	// validWaiver 返回某要求当前有效的免修。
513	func (s *Store) validWaiver(studentID, reqID string) *Waiver {
514		for _, w := range s.waivers {
515			if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
516				return w
517			}
518		}
519		return nil
520	}
521	
522	// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
523	// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
524	// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
525	//
526	// 学生编号与免修编号按用户给出的完整文字参与匹配，前后空白（普通空格、
527	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
528	// “s1”与“ s1 ”两名学生、同一学生名下“w1”与“ w1 ”两份免修，撤销
529	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
530	// 学生存在但名下没有该完整免修编号时报告该免修不存在——即使去掉空白后
531	// 能碰上另一名学生或另一份免修，也绝不借用那份记录，更不能改写原编号、
532	// 合并申请或新增免修历史。撤销提示与免修历史一律使用实际命中的原编号。
533	func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
534		reason = strings.TrimSpace(reason)
535		if _, ok := s.studentByID[studentID]; !ok {
536			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
537		}
538		w = s.waiverByKey[reqKey(studentID, waiverID)]
539		if w == nil {
540			return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
541		}
542		switch w.Status {
543		case WaiverApproved:
544			w.Status = WaiverRevoked
545			if reason == "" {
546				reason = "手动撤销"
547			}
548			w.Reason = reason
549			s.dirty = true
550			return w, true, nil
551		case WaiverRevoked:
552			return w, false, nil
553		default:
554			return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
555		}
556	}
557

