1	package credit
2	
3	import (
4		"math"
5		"strings"
6		"testing"
7	)
8	
9	// setupOverflowStore 建立两名学生、两门分别为 MaxInt 与 1 学分的课程，
10	// 以及各自指向两门课程的要求 r1/r2，均不产生修读或免修。
11	func setupOverflowStore(t *testing.T) *Store {
12		t.Helper()
13		s := NewStore()
14		mustStudent(t, s, "s1")
15		mustStudent(t, s, "s2")
16		mustCourse(t, s, "c-big", "上限课", math.MaxInt)
17		mustCourse(t, s, "c-one", "一学分课", 1)
18		mustReq(t, s, "s1", "r1", "c-big")
19		mustReq(t, s, "s1", "r2", "c-one")
20		mustReq(t, s, "s2", "q1", "c-one")
21		return s
22	}
23	
24	func passEnrollment(t *testing.T, s *Store, student, req, term, enr string) {
25		t.Helper()
26		mustEnroll(t, s, student, req, term, enr)
27		if _, changed, err := s.SubmitResult(student, enr, Passed); err != nil || !changed {
28			t.Fatalf("SubmitResult(%q,%q,passed) = changed %v, err %v", student, enr, changed, err)
29		}
30	}
31	
32	// TestCheckTotalCreditsOverflowRejected 两门各自合法的课程学分为 MaxInt 与 1，
33	// 两项要求都满足时总和 MaxInt+1 超出整数范围：核对必须标记 Overflow，
34	// TotalCredits 不得回绕成负数或任何部分和。
35	func TestCheckTotalCreditsOverflowRejected(t *testing.T) {
36		s := setupOverflowStore(t)
37		passEnrollment(t, s, "s1", "r1", "2024春", "e1")
38		passEnrollment(t, s, "s1", "r2", "2024春", "e2")
39	
40		rep := s.CheckStudent("s1")
41		if !rep.Found {
42			t.Fatal("学生 s1 应存在")
43		}
44		if !rep.Overflow {
45			t.Fatalf("MaxInt+1 必须判定超限，得到 Overflow=false, Total=%d", rep.TotalCredits)
46		}
47		if rep.TotalCredits != 0 {
48			t.Fatalf("超限时不能给出回绕/截断/部分累加的总学分，得到 %d", rep.TotalCredits)
49		}
50		msg := rep.OverflowMessage()
51		if !strings.Contains(msg, "s1") {
52			t.Fatalf("拒绝说明应点名学生编号，得到 %q", msg)
53		}
54		if !strings.Contains(msg, "9223372036854775807") {
55			t.Fatalf("拒绝说明应指出可表示的最大值，得到 %q", msg)
56		}
57		if strings.Contains(rep.String(), "核对结果") ||
58			strings.Contains(rep.String(), "总学分：") {
59			t.Fatalf("超限时不能渲染正常核对报告与总学分数值，得到 %q", rep.String())
60		}
61		// 核对只读：不产生任何额外的待保存变更。
62		dirtyBefore := s.Dirty()
63		_ = s.CheckStudent("s1")
64		if s.Dirty() != dirtyBefore {
65			t.Fatal("只读核对超限前后 dirty 状态不应变化")
66		}
67	}
68	
69	// TestCheckTotalCreditsAtLimitSucceeds 只有 MaxInt 学分的要求满足时，
70	// 总学分恰好等于上限，仍应正常核对并显示完整数值；另一项只有选课或未通过
71	// 记录时不参与累计，同样不触发超限。
72	func TestCheckTotalCreditsAtLimitSucceeds(t *testing.T) {
73		// 只有第一项满足：恰为 MaxInt，正常显示完整数值。
74		s := setupOverflowStore(t)
75		passEnrollment(t, s, "s1", "r1", "2024春", "e1")
76		rep := s.CheckStudent("s1")
77		if rep.Overflow || rep.TotalCredits != math.MaxInt {
78			t.Fatalf("总学分恰为上限时应正常核对，Overflow=%v Total=%d",
79				rep.Overflow, rep.TotalCredits)
80		}
81		if !strings.Contains(rep.String(), "总学分：9223372036854775807") {
82			t.Fatalf("应显示完整上限数值，得到 %q", rep.String())
83		}
84	
85		// 第二项选课：不计学分，不触发超限，且列为未满足要求。
86		mustEnroll(t, s, "s1", "r2", "2024春", "e2")
87		rep = s.CheckStudent("s1")
88		if rep.Overflow || rep.TotalCredits != math.MaxInt {
89			t.Fatalf("选课不计学分，总学分仍应为上限，Overflow=%v Total=%d",
90				rep.Overflow, rep.TotalCredits)
91		}
92		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r2" {
93			t.Fatalf("r2 只有选课记录应列为未满足，得到 %v", rep.Unmet)
94		}
95	
96		// 第二项提交未通过：仍不计学分、不触发超限。
97		if _, changed, err := s.SubmitResult("s1", "e2", Failed); err != nil || !changed {
98			t.Fatalf("提交未通过失败：changed=%v err=%v", changed, err)
99		}
100		rep = s.CheckStudent("s1")
101		if rep.Overflow || rep.TotalCredits != math.MaxInt {
102			t.Fatalf("未通过不计学分，总学分仍应为上限，Overflow=%v Total=%d",
103				rep.Overflow, rep.TotalCredits)
104		}
105	
106		// 第二项一旦通过，立即超限。
107		passEnrollment(t, s, "s1", "r2", "2025春", "e3")
108		if rep = s.CheckStudent("s1"); !rep.Overflow {
109			t.Fatalf("第二项通过后 MaxInt+1 必须超限，Total=%d", rep.TotalCredits)
110		}
111	}
112	
113	// TestCheckOverflowDedupAndWaiverRules 超限判定必须沿用既有计分规则：
114	// 同一要求多次通过或通过修读与有效免修并存只计一份；已拒绝/已撤销且没有
115	// 通过修读的免修不计入总分。
116	func TestCheckOverflowDedupAndWaiverRules(t *testing.T) {
117		// 同一 MaxInt 要求通过两次，不与另一门 1 学分课程的满足要求叠加超限。
118		s := setupOverflowStore(t)
119		passEnrollment(t, s, "s1", "r1", "2024春", "e1")
120		passEnrollment(t, s, "s1", "r1", "2025春", "e2")
121		// r2 的 1 学分要求保持未满足。
122		rep := s.CheckStudent("s1")
123		if rep.Overflow || rep.TotalCredits != math.MaxInt {
124			t.Fatalf("同一要求多次通过只计一份，不应超限，Overflow=%v Total=%d",
125				rep.Overflow, rep.TotalCredits)
126		}
127	
128		// MaxInt 要求同时有通过修读与有效免修：仍只计一份；1 学分要求未满足。
129		if _, a, err := s.ApplyWaiver("s1", "r1", "w1", "竞赛获奖"); err != nil || a != ActionCreated {
130			t.Fatalf("有效免修申请失败：action=%v err=%v", a, err)
131		}
132		rep = s.CheckStudent("s1")
133		if rep.Overflow || rep.TotalCredits != math.MaxInt {
134			t.Fatalf("通过修读与有效免修并存只计一份，不应超限，Overflow=%v Total=%d",
135				rep.Overflow, rep.TotalCredits)
136		}
137	
138		// 1 学分要求只有已拒绝的免修（目标要求存在但再申请一个指向不存在
139		// 要求的被拒免修），不计学分，不超限。
140		if w, a, err := s.ApplyWaiver("s1", "rX", "wbad", "依据"); err != nil ||
141			a != ActionCreated || w.Status != WaiverRejected {
142			t.Fatalf("被拒绝免修登记异常：action=%v status=%v err=%v", a, w.Status, err)
143		}
144		rep = s.CheckStudent("s1")
145		if rep.Overflow || rep.TotalCredits != math.MaxInt {
146			t.Fatalf("被拒绝的免修不计学分，不应超限，Overflow=%v Total=%d",
147				rep.Overflow, rep.TotalCredits)
148		}
149	
150		// 撤销 MaxInt 要求的有效免修后有通过修读，仍满足；1 学分要求依旧未满足。
151		if _, changed, err := s.RevokeWaiver("s1", "w1", "材料无法核实"); err != nil || !changed {
152			t.Fatalf("撤销免修失败：changed=%v err=%v", changed, err)
153		}
154		rep = s.CheckStudent("s1")
155		if rep.Overflow || rep.TotalCredits != math.MaxInt {
156			t.Fatalf("撤销后有通过记录的要求继续满足，仍只有一份上限学分，Overflow=%v Total=%d",
157				rep.Overflow, rep.TotalCredits)
158		}
159	
160		// 1 学分要求改为有效免修后才超限（MaxInt 要求由通过修读满足）。
161		if _, a, err := s.ApplyWaiver("s1", "r2", "w2", "外校课程"); err != nil || a != ActionCreated {
162			t.Fatalf("r2 有效免修申请失败：action=%v err=%v", a, err)
163		}
164		if rep = s.CheckStudent("s1"); !rep.Overflow || rep.TotalCredits != 0 {
165			t.Fatalf("两项要求都满足时必须超限且不给部分和，Overflow=%v Total=%d",
166				rep.Overflow, rep.TotalCredits)
167		}
168	}
169	
170	// TestCheckOverflowIsPerStudent 只有实际超限的学生被拒绝：另一名学生取得的
171	// 学分完全不参与，其正常核对（包括恰好等于上限的总学分）不受影响。
172	func TestCheckOverflowIsPerStudent(t *testing.T) {
173		s := setupOverflowStore(t)
174		// s1 两项都满足，必然超限。
175		passEnrollment(t, s, "s1", "r1", "2024春", "e1")
176		passEnrollment(t, s, "s1", "r2", "2024春", "e2")
177		// s2 只有一门 1 学分要求，正常核对。
178		passEnrollment(t, s, "s2", "q1", "2024春", "f1")
179	
180		rep1 := s.CheckStudent("s1")
181		rep2 := s.CheckStudent("s2")
182		if !rep1.Overflow {
183			t.Fatal("s1 应超限")
184		}
185		if rep2.Overflow || rep2.TotalCredits != 1 {
186			t.Fatalf("s2 不应受 s1 影响，Overflow=%v Total=%d", rep2.Overflow, rep2.TotalCredits)
187		}
188	}
