1	package credit
2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件为“读取已有成绩记录时，两次独立的成绩提交不能共用同一个结果提交
12	// 序号”这项既有行为提供回归保障。该冲突无法经正常提交流程落入文件（每次
13	// 提交都从递增计数器取号），因此全部用例直接构造记录文件，聚焦 Load 读取
14	// 历史这一路径：
15	//   - 文件完整可解析、学生/课程/要求齐全、修读归属与结果状态合法，只要两条
16	//     不同的修读（都已提交结果）共用同一个正整数序号，就整份判为损坏：
17	//     无论两条都通过还是一条未通过，无论它们是同一学生的重复修读、同一学生
18	//     不同要求的独立提交，还是不同学生的独立修读；即使文件里另有完全正常的
19	//     学生，也不能只读入正常部分继续核对；
20	//   - 修读编号相同、学期相同、记录在文件里的排列顺序，都不是冲突依据；
21	//   - 合法记录中两次通过按“提交序号较小者”说明来源，与文件排列、修读编号、
22	//     学期先后都无关；更早提交的未通过保留在历史中但不成为来源；
23	//   - 只有选课、尚未提交结果的修读一律使用序号 0，多条并存合法且不得学分；
24	//     已提交序号允许有间隔；不同学生共用修读编号但序号不同时各自保留归属。
25	//
26	// 所有合法用例都断言只读核对不改动原文件。
