28	// seqBaseRecord 构造结构完整、引用齐全的基础记录：学生 s1 的要求 r1 指向
29	// 4 学分课程 c1。修读与序号计数器由各用例自行补充。
30	func seqBaseRecord() *fileData {
31		return &fileData{
32			Version:      recordVersion,
33			Courses:      []*Course{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
34			Students:     []*Student{{ID: "s1"}},
35			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
36		}
37	}
