39	// seqEnr 构造一条修读记录；result 为 enrolled 时 seq 传 0。
40	func seqEnr(id, student, req, term string, result Result, seq int) *Enrollment {
41		return &Enrollment{
42			ID: id, StudentID: student, ReqID: req, Term: term,
43			Result: result, ResultSeq: seq,
44		}
