82	// TestLoadRejectsDuplicateResultSeq 文件完整、引用齐全、归属与结果合法，
83	// 但两条不同的已提交修读共用同一个正整数序号时，无论两条结果如何、归属
84	// 如何、排列如何，都必须整份判为损坏并保留原文件。
85	func TestLoadRejectsDuplicateResultSeq(t *testing.T) {
86		t.Run("两条通过_同一学生同一学期重复修读", func(t *testing.T) {
87			// 同一学期重复修读本身合法（编号不同即可），但共用序号仍是损坏。
88			d := seqBaseRecord()
89			d.Enrollments = []*Enrollment{
90				seqEnr("e1", "s1", "r1", "2024春", Passed, 7),
91				seqEnr("e2", "s1", "r1", "2024春", Passed, 7),
92			}
93			d.NextResultSeq = 7
94			assertDupSeqRejected(t, d, 7)
95		})
96	
97		t.Run("一条通过一条未通过", func(t *testing.T) {
98			// 未通过同样占用一次提交序号：一条通过、一条未通过共用序号也损坏。
99			d := seqBaseRecord()
100			d.Enrollments = []*Enrollment{
101				seqEnr("e1", "s1", "r1", "2024春", Passed, 5),
102				seqEnr("e2", "s1", "r1", "2024秋", Failed, 5),
103			}
104			d.NextResultSeq = 5
105			assertDupSeqRejected(t, d, 5)
106		})
107	
108		t.Run("同一学生不同要求的独立提交", func(t *testing.T) {
109			// 序号刻画的是两次独立提交的先后关系，不按要求划分：不同要求下的
110			// 两次提交共用序号同样损坏。
111			d := seqBaseRecord()
112			d.Courses = append(d.Courses, &Course{ID: "c2", Name: "大学物理", Credit: 3, Open: true})
113			d.Requirements = append(d.Requirements, &Requirement{ID: "r2", StudentID: "s1", CourseID: "c2"})
114			d.Enrollments = []*Enrollment{
115				seqEnr("e1", "s1", "r1", "2024春", Passed, 4),
116				seqEnr("e9", "s1", "r2", "2024春", Passed, 4),
117			}
118			d.NextResultSeq = 4
119			assertDupSeqRejected(t, d, 4)
120		})
121	
122		t.Run("不同学生的独立修读_同编号同学期", func(t *testing.T) {
123			// 修读编号、学期在学生之间相同都合法；唯一不能共用的是提交序号。
124			d := seqBaseRecord()
125			d.Students = append(d.Students, &Student{ID: "s2"})
126			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c1"})
127			d.Enrollments = []*Enrollment{
128				seqEnr("e1", "s1", "r1", "2024春", Passed, 3),
129				seqEnr("e1", "s2", "r1", "2024春", Failed, 3),
130			}
131			d.NextResultSeq = 3
132			assertDupSeqRejected(t, d, 3)
133		})
134	
135		t.Run("重复序号不相邻_夹杂其他提交", func(t *testing.T) {
136			// 文件排列顺序不是判定依据：两条同序号记录之间夹着另一条合法提交，
137			// 仍要揪出重复，不能只比较相邻记录或按读取顺序放过。
138			d := seqBaseRecord()
139			d.Enrollments = []*Enrollment{
140				seqEnr("e1", "s1", "r1", "2024春", Passed, 6),
141				seqEnr("e3", "s1", "r1", "2025春", Failed, 8),
142				seqEnr("e2", "s1", "r1", "2024秋", Passed, 6),
143			}
144			d.NextResultSeq = 8
145			assertDupSeqRejected(t, d, 6)
146		})
147	
148		t.Run("另有完全正常的学生仍整份拒绝", func(t *testing.T) {
149			// s2 的课程、要求、修读与序号全部合法：s1 名下的序号冲突仍使整份
150			// 文件不可读，不能只读入 s2 继续核对。
151			d := seqBaseRecord()
152			d.Courses = append(d.Courses, &Course{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
153			d.Students = append(d.Students, &Student{ID: "s2"})
154			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c2"})
155			d.Enrollments = []*Enrollment{
156				seqEnr("e1", "s1", "r1", "2024春", Passed, 2),
157				seqEnr("e2", "s1", "r1", "2024秋", Failed, 2),
158				seqEnr("e1", "s2", "r1", "2024春", Passed, 4),
159			}
160			d.NextResultSeq = 4
161			path, raw := writeRecord(t, d)
162			s, existed, err := Load(path)
163			if err == nil {
164				t.Fatalf("s1 的序号冲突应让整份文件不可读，却得到 store=%v", s)
165			}
166			if s != nil || !existed {
167				t.Fatalf("不得返回 s2 的部分记录，s=%v existed=%v", s, existed)
168			}
169			if !strings.Contains(err.Error(), "结果提交序号 2 重复") {
170				t.Fatalf("冲突应归属 s1 重复的序号 2，得到：%v", err)
171			}
172			got, readErr := os.ReadFile(path)
173			if readErr != nil {
174				t.Fatal(readErr)
175			}
176			if string(got) != string(raw) {
177				t.Fatal("整份拒绝时不得改写原文件")
178			}
179		})
180	}
