266	// TestLoadEarlierFailedSubmissionStaysHistoryNotSource 存在比两次通过更早
267	// 提交的未通过修读时，它必须保留在修读历史中（结果与序号不变），但不能
268	// 取代序号最小的通过修读成为学分来源；总学分仍是一份 4 学分。
269	func TestLoadEarlierFailedSubmissionStaysHistoryNotSource(t *testing.T) {
270		// 文件排列刻意打乱：e1 未通过（序号 1、学期反而更晚），两条通过分别
271		// 是序号 3 的 e2 与序号 2 的 e3。来源应是通过修读中序号最小的 e3。
272		d := seqBaseRecord()
273		d.Enrollments = []*Enrollment{
274			seqEnr("e2", "s1", "r1", "2024秋", Passed, 3),
275			seqEnr("e1", "s1", "r1", "2025春", Failed, 1),
276			seqEnr("e3", "s1", "r1", "2024春", Passed, 2),
277		}
278		d.NextResultSeq = 3
279		s := loadLegalRecord(t, d)
280	
281		rep := s.CheckStudent("s1")
282		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
283			t.Fatalf("有通过修读时要求应满足、总学分 4，得到学分=%d 未满足=%v",
284				rep.TotalCredits, rep.Unmet)
285		}
286		st := rep.Requirements[0]
287		if st.Source != "enrollment" || st.PassedEnrollmentID != "e3" {
288			t.Fatalf("来源应是通过修读中序号最小的 e3，未通过不能成为来源，得到 %+v", st)
289		}
290		if len(st.PassedEnrollmentIDs) != 2 ||
291			st.PassedEnrollmentIDs[0] != "e3" || st.PassedEnrollmentIDs[1] != "e2" {
292			t.Fatalf("通过历史应只含两次通过并按序号排列，得到 %v", st.PassedEnrollmentIDs)
293		}
294	
295		// 更早提交的未通过记录保留在历史中，结果与序号不变。
296		failed := s.Enrollment("s1", "e1")
297		if failed == nil || failed.Result != Failed || failed.ResultSeq != 1 || failed.Term != "2025春" {
298			t.Fatalf("更早提交的未通过修读应原样保留在历史中，得到 %+v", failed)
299		}
300		if n := len(s.Enrollments("s1")); n != 3 {
301			t.Fatalf("三条修读记录都应保留，得到 %d 条", n)
302		}
303	}
