270	// TestCLIMultipleEnrolledZeroSeqLegalAndWorthNoCredit 只有选课、尚未提交
271	// 结果的修读统一使用序号 0：同一学期多条选课、跨学生并存都合法，不能因
272	// 共享 0 而报重复，也不能由此获得学分；只读访问不改文件。
273	func TestCLIMultipleEnrolledZeroSeqLegalAndWorthNoCredit(t *testing.T) {
274		d := seqDupBase()
275		d.Students = append(d.Students, diskStudent{ID: "s2"})
276		d.Requirements = append(d.Requirements, diskReq{ID: "r1", Student: "s2", Course: "c1"})
277		d.Enrollments = []diskEnr{
278			// 尚未提交结果的修读按现有格式不带 resultSeq（即 0）。
279			{ID: "e1", Student: "s1", Req: "r1", Term: "2024春", Result: "enrolled"},
280			{ID: "e2", Student: "s1", Req: "r1", Term: "2024春", Result: "enrolled"},
281			{ID: "e3", Student: "s1", Req: "r1", Term: "2024秋", Result: "enrolled"},
282			// 跨学生共用修读编号，同样没有提交序号。
283			{ID: "e1", Student: "s2", Req: "r1", Term: "2024春", Result: "enrolled"},
284		}
285		d.NextResultSeq = 0
286		file, raw := writeDiskRecord(t, d)
287	
288		for _, student := range []string{"s1", "s2"} {
289			out, _, code := runCLI(t, file, "check", student)
290			if code != 0 {
291				t.Fatalf("学生 %s 的多条选课记录应正常读取，code=%d out=%q", student, code, out)
292			}
293			if !strings.Contains(out, "总学分：0") ||
294				!strings.Contains(out, "未满足要求：[r1]") ||
295				strings.Contains(out, "通过修读") {
296				t.Fatalf("学生 %s 的选课不应获得学分或出现通过来源，out=%q", student, out)
297			}
298		}
299		show, _, code := runCLI(t, file, "show", "s1")
300		if code != 0 || strings.Count(show, "结果：选课") != 3 {
301			t.Fatalf("s1 应有三条选课记录，code=%d out=%q", code, show)
302		}
303		show2, _, code := runCLI(t, file, "show", "s2")
304		if code != 0 || strings.Count(show2, "结果：选课") != 1 ||
305			strings.Contains(show2, "修读 e2") || strings.Contains(show2, "修读 e3") {
306			t.Fatalf("s2 只应有本人的一条选课，不能看到 s1 的记录，out=%q", show2)
307		}
308		assertFileByteIdentical(t, file, raw, "多条选课只读之后：")
309	}
310	
311	// TestCLISubmittedSeqGapsNeedNotBeConsecutive 已提交序号允许有间隔：跳号
312	// 记录正常读取与核对，来源仍是通过记录中序号最小的一条；未通过不成为来源，
313	// 选课记录不携带序号；只读访问不改文件。
314	func TestCLISubmittedSeqGapsNeedNotBeConsecutive(t *testing.T) {
315		d := seqDupBase()
316		d.Enrollments = []diskEnr{
317			enrRecord("e1", "s1", "r1", "2024春", "failed", 1),
318			enrRecord("e2", "s1", "r1", "2024夏", "passed", 5), // 序号 2/3/4 缺失
319			enrRecord("e3", "s1", "r1", "2024秋", "passed", 9), // 继续跳号
320			{ID: "e4", Student: "s1", Req: "r1", Term: "2025春", Result: "enrolled"},
321		}
322		d.NextResultSeq = 9
323		file, raw := writeDiskRecord(t, d)
324	
325		out, _, code := runCLI(t, file, "check", "s1")
326		if code != 0 {
327			t.Fatalf("跳号的合法记录应正常核对，code=%d out=%q", code, out)
328		}
329		if !strings.Contains(out, "总学分：4") ||
330			!strings.Contains(out, "来源为通过修读 e2") ||
331			!strings.Contains(out, "共通过 2 次，仅计一次学分") ||
332			strings.Contains(out, "未满足要求：[") {
333			t.Fatalf("跳号不应影响核对：来源应是通过中序号最小的 e2、两次通过只计一次，out=%q", out)
334		}
335		if strings.Contains(out, "来源为通过修读 e1") {
336			t.Fatalf("序号 1 的未通过不能成为来源，out=%q", out)
337		}
338		show, _, _ := runCLI(t, file, "show", "s1")
339		if !strings.Contains(show, "修读 e1：要求 r1，学期 2024春，结果：未通过") ||
340			!strings.Contains(show, "修读 e4：要求 r1，学期 2025春，结果：选课") {
341			t.Fatalf("未通过与选课记录都应原样保留，out=%q", show)
342		}
343		assertFileByteIdentical(t, file, raw, "跳号记录只读之后：")
344	}
345	
346	// TestCLISameEnrollmentIDAcrossStudentsDifferentSeq 不同学生共用修读编号与
347	// 学期、但提交序号不同：各自的记录正常读取、核对各归本人，不能因编号或
348	// 学期相同误报冲突或串记录；文件排列与提交先后不一致时结论不变。
349	func TestCLISameEnrollmentIDAcrossStudentsDifferentSeq(t *testing.T) {
350		d := &diskRecord{
351			Version: 1,
352			Courses: []diskCourse{
353				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
354				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
355			},
356			Students: []diskStudent{{ID: "s1"}, {ID: "s2"}},
357			Requirements: []diskReq{
358				{ID: "r1", Student: "s1", Course: "c1"},
359				{ID: "r1", Student: "s2", Course: "c2"},
360			},
361			Enrollments: []diskEnr{
362				// 后提交的 s2 记录排在文件前面：来源只看本人的提交序号。
363				enrRecord("e1", "s2", "r1", "2024春", "passed", 2),
364				enrRecord("e1", "s1", "r1", "2024春", "passed", 1),
365			},
366			NextResultSeq: 2,
367		}
368		file, raw := writeDiskRecord(t, d)
369	
370		out, _, code := runCLI(t, file, "check", "s1")
371		if code != 0 {
372			t.Fatalf("s1 的合法记录应正常核对，code=%d out=%q", code, out)
373		}
374		if !strings.Contains(out, "总学分：4") ||
375			!strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：已满足") ||
376			!strings.Contains(out, "来源为通过修读 e1") {
377			t.Fatalf("s1 应凭本人 e1 获得本人 4 学分课程，out=%q", out)
378		}
379	
380		out, _, code = runCLI(t, file, "check", "s2")
381		if code != 0 {
382			t.Fatalf("s2 的合法记录应正常核对，code=%d out=%q", code, out)
383		}
384		if !strings.Contains(out, "总学分：3") ||
385			!strings.Contains(out, "要求 r1（课程 c2《线性代数》，3 学分）：已满足") ||
386			!strings.Contains(out, "来源为通过修读 e1") {
387			t.Fatalf("s2 应凭本人 e1 获得本人 3 学分课程，编号相同不构成冲突，out=%q", out)
388		}
389	
390		// show 各归各：只能看到本人的修读与课程，不能串到另一人。
391		show1, _, _ := runCLI(t, file, "show", "s1")
392		if !strings.Contains(show1, "修读 e1：要求 r1，学期 2024春，结果：通过") ||
393			strings.Contains(show1, "线性代数") {
394			t.Fatalf("s1 的历史应只含本人修读与本人课程，out=%q", show1)
395		}
396		show2, _, _ := runCLI(t, file, "show", "s2")
397		if !strings.Contains(show2, "修读 e1：要求 r1，学期 2024春，结果：通过") ||
398			strings.Contains(show2, "高等数学") {
399			t.Fatalf("s2 的历史应只含本人修读与本人课程，out=%q", show2)
400		}
401	
402		assertFileByteIdentical(t, file, raw, "跨学生同号不同序号只读之后：")
403	}
